/** 写信台 peek 落账：一槽一 briefKey；同 bookKey 多槽不合并；仅充分才铸；写入 llmCall 进度边 */
export function settlePeekItemsFromLlm(input: {
  docId: string
  llmText: string
  allowedBookKeys: ReadonlyArray<string>
  /** 本问原文：用于 pushPeekStep / 进度边挂 queryKey */
  question?: string
  /** 同一次 peek LLM 调用批 id；缺则现铸 */
  llmCallId?: string
}): { items: A1DsItem[]; note: string; skipped: number; llmCallId?: string } {
  const allowed = new Set(input.allowedBookKeys)
  const parsed = parseFlashResponse(input.llmText, allowed)
  const hung: A1DsItem[] = []
  let skipped = 0
  for (const it of parsed.items) {
    if (!statusAllowsMint(it.status)) {
      skipped++
      continue
    }
    const entry = rollDoorBrief({
      docId: input.docId,
      key: it.key,
      decisionBrief: it.brief,
      suggestAction: 'open',
      taskId: `desk_peek_${Date.now().toString(36)}`,
    })
    hung.push({ ...it, briefKey: entry.briefKey })
  }

  let llmCallId: string | undefined
  if (hung.length > 0) {
    llmCallId = input.llmCallId?.trim() || newLlmCallId('peek')
    const question = input.question?.trim() || ''
    if (question) {
      useAttentionIo.getState().pushPeekStep({
        question,
        items: hung.map((it) => ({
          key: it.key,
          brief: it.brief,
          briefKey: it.briefKey,
        })),
        mode: 'cold',
        llmCallId,
      })
    } else {
      const qk = useAttentionIo.getState().ensureQueryKey('(desk peek)')
      useAttentionIo.getState().registerLlmCallBatch({
        llmCallId,
        job: 'peek',
        memberKeys: hung
          .map((it) => it.briefKey)
          .filter((k): k is string => Boolean(k)),
        queryKey: qk,
        keyKind: 'brief',
      })
    }
  }

  return {
    items: hung,
    skipped,
    llmCallId,
    note:
      hung.length > 0
        ? `peek 落账 briefKey×${hung.length}` +
          (llmCallId ? ` · ${llmCallId}` : '') +
          (skipped ? ` · 非充分跳过×${skipped}` : '') +
          (parsed.recovered ? ' · 已修复JSON' : '')
        : skipped > 0
          ? `peek 无充分槽（跳过×${skipped}）`
          : 'peek 无有效输出槽',
  }
}

