  const opened = new Set(input.openedKeys ?? [])

  /** 冷启：多 KEY/批 + 多批并行 API；绝不是一 KEY 一次调用 */
  const COLD_BATCH = 36
  const COLD_CONCURRENCY = 3
  const batches: A1DsRow[][] =
    peekMode === 'cold' && rows.length > COLD_BATCH
      ? (() => {
          const out: A1DsRow[][] = []
          for (let i = 0; i < rows.length; i += COLD_BATCH) {
            out.push(rows.slice(i, i + COLD_BATCH))
          }
          return out
        })()
      : [rows]

  input.onProgress?.(
    peekMode === 'hot'
      ? `DeepSeek Flash · 热启 peek（书序 N=${rows.length}）→ 铸门贴…`
      : batches.length > 1
        ? `DeepSeek Flash · 冷启并行 peek（${rows.length} 行 → ${batches.length} 批×≤${COLD_BATCH} · 并发 ${COLD_CONCURRENCY}）…`
        : `DeepSeek Flash 读取整表 A1（${rows.length} 行 KEY+T）→ 铸门贴…`,
  )

  type BatchPeekResult = {
    bi: number
    ok: boolean
    note?: string
    items: A1DsItem[]
    skipped: number
    recovered: boolean
    answer: string
    refused: boolean
  }

  const runOneBatch = async (bi: number): Promise<BatchPeekResult> => {
    const batch = batches[bi]!
    const allowedBatch = new Set(batch.map((r) => r.key))
    const system = [
      a1DsPromptRules(),
      peekInstruction,
      peekMode === 'hot'
        ? PEEK_HOT_INSTRUCTION_SUFFIX
        : '【冷启】从本批书序 KEY+T 点名勾门铸贴；KEY 须原样复制。',
      batches.length > 1
        ? `【并行分批 ${bi + 1}/${batches.length}】本消息只有本批 ${batch.length} 行书序连续 KEY+T（全书共 ${rows.length} 行，其它批由台并行另调）。只从本批 KEY 勾选并铸 brief；禁止空 briefs；禁止要求「请分批输入」。`
        : '',
      attachUser
        ? '【二次+ peek】可参考用户原话旁注理解修贴意图；brief 仍只从 T 提炼。'
        : '【第一次冷启】不要依赖用户问题；只按固定指令从 T 铸贴。',
      opened.size > 0 && peekMode === 'hot'
        ? `已开门牌（有 head）：${[...opened].slice(0, 12).join(', ')}${opened.size > 12 ? '…' : ''} —— 禁止当处女再 create；仅缺口才输出新 brief。`
        : '',
      '只输出 JSON（可包在 ```json 里），不要散文。',
    ]
      .filter(Boolean)
      .join('\n')

    const user = [
      `【peek 指令】\n${peekInstruction}`,
      attachUser && qSide ? `${PEEK_USER_ASIDE_HINT}\n${qSide}` : '',
      '',
      peekMode === 'hot'
        ? `【A1 书序区间 · ${batch.length} 行 · 仅 KEY+T】`
        : batches.length > 1
          ? `【A1 冷启批 ${bi + 1}/${batches.length} · 书序连续 ${batch.length} 行 · 仅 KEY+T】`
          : `【A1 整表 · ${batch.length} 行 · 仅 KEY+T】`,
      compactTable(batch),
    ]
      .filter(Boolean)
      .join('\n')

    const chat = await flashChat({ system, user, temperature: 0.1 })
    if (!chat.ok) {
      return {
        bi,
        ok: false,
        note: chat.note,
        items: [],
        skipped: 0,
        recovered: false,
        answer: '',
        refused: false,
      }
    }

    const parsed = parseFlashResponse(chat.content, allowedBatch)
    const refused =
      parsed.items.length === 0 &&
      /分批|无法.*铸|随机.*bookKey|校验.*bookKey/i.test(parsed.answer || '')

    const { deskMonitorAttentionArrival } = await import('./attentionArrival')
    deskMonitorAttentionArrival({
      job: 'peek',
      llmText: chat.content,
      windowKeys: [...allowedBatch],
    })

    const items: A1DsItem[] = []
    let skipped = 0
    for (const it of parsed.items) {
      if (!statusAllowsMint(it.status)) {
        skipped++
        continue
      }
      const entry = rollDoorBrief({
        docId: input.bookIndex.docId,
        key: it.key,
        decisionBrief: it.brief,
        suggestAction: 'open',
        taskId: `a1chat_${Date.now().toString(36)}_${bi}`,
      })
      items.push({ ...it, briefKey: entry.briefKey })
    }

    return {
      bi,
      ok: true,
      items,
      skipped,
      recovered: Boolean(parsed.recovered),
      answer: parsed.answer || '',
      refused,
    }
  }

  /** 波次并行：每波最多 COLD_CONCURRENCY 批；凑够 MAX_ITEMS 就停后续波 */
  const hung: A1DsItem[] = []
  let skipped = 0
  let recoveredAny = false
  let lastAnswer = ''
  let packsScanned = 0
  let firstFailNote = ''

  for (let start = 0; start < batches.length; start += COLD_CONCURRENCY) {
    if (hung.length >= MAX_ITEMS) break
    const wave = [] as number[]
    for (
      let j = start;
      j < Math.min(start + COLD_CONCURRENCY, batches.length);
      j++
    ) {
      wave.push(j)
    }
    input.onProgress?.(
      batches.length > 1
        ? `冷启 peek · 并行波次 批 ${wave.map((i) => i + 1).join('+')}/${batches.length}…`
        : undefined,
    )
    const waveResults = await Promise.all(wave.map((bi) => runOneBatch(bi)))
    packsScanned += waveResults.length

    // 按书序合并本波结果
    waveResults.sort((a, b) => a.bi - b.bi)
    for (const r of waveResults) {
      if (!r.ok) {
        if (!firstFailNote && r.note) firstFailNote = r.note
        continue
      }
      if (r.recovered) recoveredAny = true
      if (r.answer) lastAnswer = r.answer
      skipped += r.skipped
      for (const it of r.items) {
        if (hung.length >= MAX_ITEMS) break
        hung.push(it)
      }
      if (r.refused) {
        input.onProgress?.(
          `冷启 peek · 批 ${r.bi + 1} 拒铸（已并行续其它批）`,
        )
      }
    }
  }

  if (hung.length === 0 && firstFailNote && packsScanned > 0) {
    return {
      ok: false,
      keys: [],
      items: [],
      answer: '',
      note: firstFailNote,
      packsScanned,
    }
  }

  const keys = hung.map((h) => h.key)
  const note =
    hung.length > 0
      ? `${recoveredAny ? '已从破损 JSON 捞回 · ' : ''}${peekMode === 'hot' ? '热启' : '冷启'}已铸 ${hung.length} 条门贴并挂靠 bookKey` +
        (skipped ? ` · 非充分跳过×${skipped}` : '') +
        ` · 表 ${rows.length} 行 · 并行扫 ${packsScanned} 批`
      : `未得到充分 brief · ${peekMode === 'hot' ? '热启区间' : '整表'} ${rows.length} 行 · 并行扫 ${packsScanned} 批` +
        (skipped ? ` · 非充分跳过×${skipped}` : '') +
        (lastAnswer ? ` · 模型：${lastAnswer.slice(0, 80)}` : '')

  return {
    ok: true,
    keys,
    items: hung,
    answer:
      lastAnswer ||
      (hung.length
        ? hung.map((h) => `${h.key.slice(0, 24)}…：${h.brief}`).join('\n')
        : '（无门贴）'),
    note,
    packsScanned,
  }
}

